#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_compact_shrinks_and_copies_data(void) {
    // Setup: Create a buffer with extra capacity and some data
    // We'll use buffer_new_with_size and then buffer_append to fill it
    size_t initial_capacity = 32;
    buffer_t *buf = buffer_new_with_size(initial_capacity);
    TEST_ASSERT_NOT_NULL(buf);

    // Fill with a string shorter than the capacity
    const char *test_str = "hello world";
    int append_ret = buffer_append(buf, test_str);
    TEST_ASSERT_EQUAL_INT(0, append_ret);

    // Confirm initial state: buffer size > string length
    size_t str_len = strlen(test_str);
    helper_assert_buffer_length(buf, str_len);
    helper_assert_buffer_size(buf, initial_capacity);
    helper_assert_buffer_string_equals(buf, test_str);

    // Call buffer_compact
    ssize_t freed = buffer_compact(buf);

    // After compaction, buffer size should match string length
    helper_assert_buffer_length(buf, str_len);
    helper_assert_buffer_size(buf, str_len);
    helper_assert_buffer_string_equals(buf, test_str);

    // The number of bytes freed should be initial_capacity - str_len
    TEST_ASSERT_EQUAL_INT((ssize_t)(initial_capacity - str_len), freed);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_compact_shrinks_and_copies_data);
    return UNITY_END();
}


